/**
 * Product response schema
 */
export interface ProductResponse {
  /** Unique product identifier */
  product_id: string;
  /** The product_id with its weekly date suffix stripped — stable across promo weeks, so it is the key to deduplicate on. Most chains mint a new product_id whenever a promotion starts (a re-promoted or daily-renewed offer therefore looks like a new product), and this is the same SKU behind those. Jumbo, Ekoplaza and Vomar carry no date suffix, so for them it equals product_id. ⚠️ Not a cross-retailer identifier and not stable at Vomar, whose ids are derived per folder and rotate weekly — use ean to match across chains. */
  base_product_id: string;
  /** Product name */
  name: string;
  /** Brand name */
  brand?: string | null;
  /** EAN/GTIN barcode. Published by Albert Heijn, Jumbo and partly Ekoplaza; null for the other seven chains. */
  ean?: string | null;
  /** Product image URL */
  image_url?: string | null;
  /** What the product costs today: the promotional price while a promotion runs, the regular price otherwise. ⚠️ It is the price of ONE item at every chain except Aldi, which publishes the bundle total as its price — so '2 VOOR 0.79' reads price=0.79 for TWO items there. Read it together with multi_buy_quantity to tell the two apart: where that field is set and Aldi is the retailer, price buys multi_buy_quantity items. At PLUS a multipack's price is the price of the pack, which is the one unit you can buy. Use unit_price to compare across pack sizes. */
  price: number;
  /** Price before the promotion (the 'was' price) */
  original_price?: number | null;
  /** Discount percentage */
  discount_percentage?: number | null;
  /** Absolute saving in EUR */
  savings_amount?: number | null;
  /** Saving as percentage */
  savings_percentage?: number | null;
  /** Bundle size the promotion names: 2 for '2 voor 3,-', 2 for '1+1 gratis'. Null when the promotion is not a bundle of two or more. `price` stays the price of ONE item wherever the chain lets us derive it; Aldi publishes the bundle total as its price. */
  multi_buy_quantity?: number | null;
  /** What the bundle costs in total: 3.0 for '2 voor 3,-', and for an N-th-free mechanism the amount that ratio comes to against the regular price — 10.99 for a '1+1 gratis' on a €10,99 item. This is the payable figure; `price` is the per-item view of it and is rounded to the cent, so multiplying it by `multi_buy_quantity` can miss the total by a cent in either direction. Null where no regular price was available. At Aldi this equals `price`, because Aldi publishes the bundle total as the product's price. */
  multi_buy_price?: number | null;
  /** Currency code */
  currency?: string;
  /** Product quantity/unit */
  quantity?: string | null;
  /** Unit of unit_price: kg, L or stuk. Null when no comparable unit exists, e.g. one price over several pack sizes */
  unit?: string | null;
  /** Price per normalised unit */
  unit_price?: number | null;
  /** The category as the retailer itself publishes it, verbatim. Every chain has its own taxonomy, so these strings are NOT comparable across retailers — use unified_category for that. Albert Heijn publishes it as 'Hoofdcategorie/Subcategorie'. Null at Aldi, Hoogvliet and Vomar, which publish no category at all; Lidl publishes the single constant 'Food' on every product, so treat that as absent too. */
  retailer_category?: string | null;
  /** One of the 18 unified category slugs. Derived: we take the retailer's own category where it is unambiguous and fall back to the product name otherwise — a normalisation across 10 chains, not the retailer's own taxonomy. Aldi, Hoogvliet and Vomar publish no category at all, so theirs is name-based. */
  unified_category?: string | null;
  /** bio | glutenvrij | lactosevrij | vegan | vegetarisch. Derived from product names and brand rules — indicative, not allergen information. */
  dietary_tags?: string[];
  /** Whether this is a retailer's own brand (private label) */
  private_label?: boolean | null;
  /** Nutri-Score grade a-e (lowercase). Scraped from Albert Heijn only, but propagated to other retailers on GET /products/{id} via an exact EAN match (#979) — a product's formulation doesn't change by shop. */
  nutriscore?: string | null;
  /** Product detail page URL */
  product_url?: string | null;
  /** Retailer name */
  retailer: string;
  /** Associated folder ID (legacy, unused for scraped products) */
  folder_id?: string | null;
  /** Page number in PDF */
  page_number?: number | null;
  /** Whether product is on promotion */
  is_promotional?: boolean;
  /** Promotion mechanism, one fixed vocabulary for every retailer: `percentage` (a price cut, incl. a plain was/now price), `multi_buy` ('2 voor 6,00', '3 stuks €5'), `one_plus_one` ('1+1 gratis', '2+1 gratis', '2e halve prijs'), `volume`, `limited` ('OP=OP'), `starting` ('vanaf'). Null when the retailer's label names no mechanism we can classify. */
  promotion_type?: string | null;
  /** The retailer's own id for the promotion this product takes part in, namespaced by retailer. Every product in the same promotion carries the same value, so `GET /api/v1/products?promo_group_id=...` lists them all. Scoped to the promotion week. Null when the retailer publishes no id. */
  promo_group_id?: string | null;
  /** True when the retailer states the products in this group combine toward one deal (e.g. 'Kies & Mix 2 voor 6,00'); false when it states the deal applies per product. Null when the retailer does not say: a shared `promo_group_id` alone does not prove the products can be mixed. */
  promo_group_mixable?: boolean | null;
  /** Promotion status */
  promotion_status?: string | null;
  /** Promotional keywords */
  promotional_keywords?: string[];
  /** Promotion start (ISO date) */
  valid_from?: string | null;
  /** Promotion end (ISO date) */
  valid_until?: string | null;
  /** True when valid_until is OUR rolling estimate, not a date the retailer published. Today only PLUS long-running promotions: its feed carries no end date, so the end is re-extended by two days on every nightly run while the promotion stays in the feed, and can outlast the real promotion by up to two days. Null means not assessed — not 'retailer-stated'. */
  valid_until_estimated?: boolean | null;
  /** True when the retailer itself states the promotion holds only in the shop, not in its webshop. Filled where the chain says so: Albert Heijn's own store-only flag on the bonus segment, Lidl's availability badge and Jumbo's label ('Alleen in de winkel'); false wherever online_only is true. Null means not assessed — the other chains publish no such signal, so no claim is made. */
  in_store_only?: boolean | null;
  /** True when the retailer itself states the promotion holds only in its webshop, not in the shop. Filled where the chain says so: Albert Heijn's online-only bonus segment and Jumbo's 'Alleen online' label; false wherever in_store_only is true. Null means not assessed, not 'also in the shop'. */
  online_only?: boolean | null;
  /** The price that holds only for members of the retailer's loyalty programme (named in loyalty_program). `price` is always what a shopper without it pays. Filled where the chain states a member price: today Lidl Plus. Null means not assessed, not 'no member price'. */
  loyalty_price?: number | null;
  /** The loyalty programme loyalty_price requires, e.g. 'Lidl Plus'. Null whenever loyalty_price is null. */
  loyalty_program?: string | null;
  /** The most times one customer may take this promotion, where the chain states it for this promotion: today Jumbo and DekaMarkt. Null means no promotion-specific limit is stated, not 'unlimited': several chains publish one house rule for every promotion, which is not copied onto rows. As published on 2026-09-21: Jumbo 4 per visit unless stated otherwise, PLUS 5 unless stated otherwise, Hoogvliet 8, Aldi 4 per visit (non-food). */
  max_per_customer?: number | null;
  /** When the product was extracted */
  extracted_at: string;
}
